import React from "react";
import { avatarColor, initials } from "../utils/helpers";

export default function Avatar({ name = "", size = "md", online = false, square = false }) {
  const sz = {
    xs: "w-7 h-7 text-[10px]",
    sm: "w-9 h-9 text-xs",
    md: "w-11 h-11 text-sm",
    lg: "w-14 h-14 text-base",
    xl: "w-16 h-16 text-lg",
  };
  const dot = {
    xs: "w-2 h-2 border",
    sm: "w-2.5 h-2.5 border-2",
    md: "w-3 h-3 border-2",
    lg: "w-3.5 h-3.5 border-2",
    xl: "w-4 h-4 border-2",
  };
  return (
    <div className="relative flex-shrink-0">
      <div className={`${sz[size] || sz.md} ${avatarColor(name)} font-display font-bold
        flex items-center justify-center select-none transition-transform
        ${square ? "rounded-2xl" : "rounded-full"}`}>
        {initials(name)}
      </div>
      {online && (
        <span className={`absolute bottom-0 right-0 ${dot[size] || dot.md}
          bg-crisp-green rounded-full border-crisp-surface`} />
      )}
    </div>
  );
}
